import type { Carrier } from '../types.ts';

const S10_WEIGHTS = [8, 6, 4, 2, 3, 5, 9, 7];

/** UPU S10 check digit for 8 serial digits (algorithm: docs/carriers.md). */
export function s10CheckDigit(serial: string): number {
  const sum = [...serial].reduce((acc, d, i) => acc + Number(d) * S10_WEIGHTS[i], 0);
  const result = 11 - (sum % 11);
  if (result === 10) return 0;
  if (result === 11) return 5;
  return result;
}

export type TrackingNumberProblem = 'format' | 'check_digit';

/** Checks an (uppercased) ATP number: 2 letters, 8 digits, check digit, `AT`. Returns null if valid. */
export function checkAtpTrackingNumber(value: string): TrackingNumberProblem | null {
  const m = /^[A-Z]{2}(\d{8})(\d)AT$/.exec(value);
  if (!m) return 'format';
  return s10CheckDigit(m[1]) === Number(m[2]) ? null : 'check_digit';
}

/**
 * Only ATP numbers are validated. All other carriers accept any non-empty value on purpose:
 * their formats change too often (valid DHL numbers were rejected for two days in 2025).
 */
export function checkTrackingNumber(carrier: Carrier, value: string): TrackingNumberProblem | null {
  return carrier === 'ATP' ? checkAtpTrackingNumber(value) : null;
}
